<template><div class="page"><header><div><h2>团购套餐</h2><p>小程序只展示已上架且在有效期内的套餐。</p></div><el-button type="primary" @click="edit()">新增套餐</el-button></header>
<el-table :data="rows" border stripe v-loading="loading"><el-table-column prop="name" label="套餐" min-width="180"/><el-table-column prop="code" label="代码" width="140"/><el-table-column label="价格" width="150"><template #default="{row}">¥{{money(row.price)}} / <s>¥{{money(row.originalPrice)}}</s></template></el-table-column><el-table-column prop="requiredQuantity" label="件数" width="70"/><el-table-column label="适用品类" min-width="160"><template #default="{row}">{{row.categoryGroups.map(x=>groups[x]||x).join('、')}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='ACTIVE'?'success':'info'">{{row.status==='ACTIVE'?'上架':'下架'}}</el-tag></template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" :title="form.id?'编辑套餐':'新增套餐'" width="620px"><el-form label-width="100px"><el-form-item label="套餐代码"><el-input v-model.trim="form.code" :disabled="!!form.id"/></el-form-item><el-form-item label="套餐名称"><el-input v-model.trim="form.name"/></el-form-item><el-form-item label="说明"><el-input v-model.trim="form.description" maxlength="500"/></el-form-item><el-form-item label="平台"><el-select v-model="form.platform"><el-option label="抖音" value="DOUYIN"/><el-option label="微信" value="WECHAT"/><el-option label="其他" value="OTHER"/></el-select></el-form-item><el-form-item label="价格"><el-input-number v-model="form.price" :min="0" :precision="2"/>　原价　<el-input-number v-model="form.originalPrice" :min="0" :precision="2"/></el-form-item><el-form-item label="套餐件数"><el-input-number v-model="form.requiredQuantity" :min="1" :max="50"/></el-form-item><el-form-item label="适用品类"><el-checkbox-group v-model="form.categoryGroups"><el-checkbox v-for="(label,key) in groups" :key="key" :value="key">{{label}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="有效期"><el-date-picker v-model="period" type="datetimerange" start-placeholder="开始" end-placeholder="结束" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="首页推荐"><el-switch v-model="form.featured"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0"/></el-form-item><el-form-item label="状态"><el-switch v-model="active" active-text="上架" inactive-text="下架"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>
import {computed,onMounted,reactive,ref} from 'vue';import {ElMessage} from 'element-plus';import {dealPackageApi} from '@/api'
const groups={CLOTHES:'衣物',SHOES:'鞋类',HOME:'家纺',IRON:'单烫',LEATHER:'皮衣护理',BAG:'包包'}
const empty=()=>({id:null,code:'',name:'',description:'',platform:'DOUYIN',price:0,originalPrice:0,requiredQuantity:1,validFrom:null,validTo:null,status:'ACTIVE',featured:false,sortOrder:0,categoryGroups:['CLOTHES']})
const rows=ref([]),loading=ref(false),visible=ref(false),saving=ref(false),form=reactive(empty())
const active=computed({get:()=>form.status==='ACTIVE',set:v=>form.status=v?'ACTIVE':'INACTIVE'}),period=computed({get:()=>form.validFrom&&form.validTo?[form.validFrom,form.validTo]:null,set:v=>{form.validFrom=v?.[0]||null;form.validTo=v?.[1]||null}})
const money=v=>Number(v||0).toFixed(2)
async function load(){loading.value=true;try{rows.value=await dealPackageApi.list()}finally{loading.value=false}}
function edit(row){Object.assign(form,empty(),row?{...row,price:Number(row.price),originalPrice:Number(row.originalPrice),categoryGroups:[...row.categoryGroups]}:{});visible.value=true}
async function save(){if(!form.code||!form.name||!form.categoryGroups.length)return ElMessage.warning('请完整填写套餐和适用品类');saving.value=true;try{await dealPackageApi.save({...form});visible.value=false;ElMessage.success('套餐已保存');await load()}finally{saving.value=false}}
onMounted(load)
</script><style scoped>.page{background:#fff;padding:24px;border-radius:12px;color:#263445}header{display:flex;justify-content:space-between;margin-bottom:22px}h2{margin:0 0 7px}p{margin:0;color:#667588}</style>
